// Observe Largest Contentful Paint (LCP)
const observer = new PerformanceObserver((entryList) => {
  const entries = entryList.getEntries();
  const lastEntry = entries[entries.length - 1]; // Latest LCP candidate

  console.log(`🎯 LCP Candidate: ${lastEntry.element?.tagName}, Render Time: ${lastEntry.startTime.toFixed(2)}ms`);

  // Dispatch metric to RUM analytics endpoint
  // sendToAnalytics({ metric: 'LCP', value: lastEntry.startTime, element: lastEntry.element?.tagName });
});

// Register LCP observer with buffered entries
observer.observe({ type: 'largest-contentful-paint', buffered: true });
